INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('ltd_p1_c1', 'thpt_le_trung_dinh_0501', '12D', 'Đạo đức, pháp luật thế giới ảo', 'single_choice', 'biet', 'ALL', 'Khi nói về ưu điểm khi giao tiếp trên không gian mạng, phương án nào sau đây đúng?', '{"A": "Tất cả công cụ, phần mềm cho việc giao tiếp đều miễn phí giúp giải quyết cho vấn đề kinh tế.", "B": "Giao tiếp trên không gian mạng giúp kết nối con người lại gần nhau hơn.", "C": "Mọi giao dịch mua bán đều diễn ra an toàn, không bị kẻ xấu lợi dụng.", "D": "Mọi thông tin tìm được trên không gian mạng đều có thể xác thực và kiểm chứng."}'::jsonb, 'B', 'Đáp án chính xác: B theo bảng chấm điểm chuẩn mã đề 501.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('ltd_p1_c2', 'thpt_le_trung_dinh_0501', '12F', 'Tạo trang web và thiết kế web', 'single_choice', 'biet', 'ALL', 'Thuộc tính nào sau đây được sử dụng để đặt màu nền cho một phần tử trong CSS?', '{"A": "background-color.", "B": "background-style.", "C": "color-background.", "D": "background."}'::jsonb, 'A', 'Đáp án chính xác: A theo bảng chấm điểm chuẩn mã đề 501.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('ltd_p1_c3', 'thpt_le_trung_dinh_0501', '12F', 'Tạo trang web và thiết kế web', 'single_choice', 'biet', 'ALL', 'Thẻ nào dưới đây được dùng để tạo một liên kết đến một trang web khác?', '{"A": "<href>", "B": "<url>", "C": "<a>", "D": "<link>"}'::jsonb, 'C', 'Đáp án chính xác: C theo bảng chấm điểm chuẩn mã đề 501.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('ltd_p1_c4', 'thpt_le_trung_dinh_0501', '12F', 'Tạo trang web và thiết kế web', 'single_choice', 'biet', 'ALL', 'Một máy tính có địa chỉ IP là 192.168.1.9, địa chỉ đó được biểu diễn ở dạng nhị phân như thế nào?', '{"A": "01011100-10101000-00000001-00001001", "B": "01011100.10101000.00000001.00001001", "C": "11000000:10101000:00000001:00001001", "D": "11000000.10101000.00000001.00001001"}'::jsonb, 'D', 'Đáp án chính xác: D theo bảng chấm điểm chuẩn mã đề 501.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('ltd_p1_c5', 'thpt_le_trung_dinh_0501', '12A', 'Trí tuệ nhân tạo (AI) & Học máy', 'single_choice', 'biet', 'ALL', 'Tố chất cá nhân nào sau đây KHÔNG phù hợp với người làm nghề kĩ sư an toàn thông tin?', '{"A": "Có tinh thần sáng tạo.", "B": "Có tính kỷ luật kém.", "C": "Cẩn thận.", "D": "Khả năng chịu áp lực cao."}'::jsonb, 'B', 'Đáp án chính xác: B theo bảng chấm điểm chuẩn mã đề 501.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('ltd_p1_c6', 'thpt_le_trung_dinh_0501', '12A', 'Trí tuệ nhân tạo (AI) & Học máy', 'single_choice', 'biet', 'ALL', 'Giả sử bạn có một thẻ <p> với nội dung trong trang web và muốn thay đổi màu sắc văn bản thành màu xanh dương, font chữ thành Arial và kích thước chữ là 16px. Cách sử dụng CSS nào sau đây là đúng?', '{"A": "p {text-color: blue; font: Arial; text-size: 16px;}", "B": "p {color: blue; font-family: Arial; font-size: 16px;}", "C": "p {background-color: blue; font: Arial; font-size: 16px;}", "D": "p {color: blue; font-family: Arial; font-size: 16px; text-align: center;}"}'::jsonb, 'B', 'Đáp án chính xác: B theo bảng chấm điểm chuẩn mã đề 501.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('ltd_p1_c7', 'thpt_le_trung_dinh_0501', '12A', 'Trí tuệ nhân tạo (AI) & Học máy', 'single_choice', 'biet', 'ALL', 'Lĩnh vực nào sau đây có thể áp dụng AI?', '{"A": "Duy nhất trong ngành công nghiệp phần mềm.", "B": "Chỉ trong các ứng dụng văn phòng.", "C": "Chỉ trong việc phát triển các trò chơi điện tử.", "D": "Trong nhiều lĩnh vực như chăm sóc sức khỏe, ô tô tự lái, tài chính, và giáo dục."}'::jsonb, 'D', 'Đáp án chính xác: D theo bảng chấm điểm chuẩn mã đề 501.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('ltd_p1_c8', 'thpt_le_trung_dinh_0501', '12B', 'Mạng máy tính và Internet', 'single_choice', 'biet', 'ALL', 'Các thiết bị nào sau đây được sử dụng để tạo thành một mạng LAN?', '{"A": "Thiết bị đầu cuối, cáp mạng, Switch, Hub.", "B": "Thiết bị đầu cuối, Access point.", "C": "Thiết bị đầu cuối, Switch, Hub, Access point.", "D": "Thiết bị đầu cuối, Switch, Hub."}'::jsonb, 'A', 'Đáp án chính xác: A theo bảng chấm điểm chuẩn mã đề 501.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('ltd_p1_c9', 'thpt_le_trung_dinh_0501', '12B', 'Mạng máy tính và Internet', 'single_choice', 'hieu', 'ALL', 'Cần sử dụng CSS để tạo hiệu ứng hover cho tất cả các thẻ <a> trong trang web. Khi người dùng di chuột vào liên kết, màu nền của nó sẽ thay đổi thành màu vàng và màu chữ thành đỏ. Câu lệnh CSS nào dưới đây là đúng?', '{"A": "a:hover {background-color: green; color: blue;}", "B": "a:hover {background-color: yellow; color: red;}", "C": "a:active {background-color: yellow; color: red;}", "D": "a:focus {background-color: yellow; color: red;}"}'::jsonb, 'B', 'Đáp án chính xác: B theo bảng chấm điểm chuẩn mã đề 501.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('ltd_p1_c10', 'thpt_le_trung_dinh_0501', '12B', 'Mạng máy tính và Internet', 'single_choice', 'hieu', 'ALL', 'Phát biểu nào dưới đây đúng khi nói về điểm chung của hai địa chỉ IP 192.168.1.5 và 192.168.1.10?', '{"A": "Bao gồm 16 bit.", "B": "Có cùng một địa chỉ máy.", "C": "Là địa chỉ IP phiên bản IPv6.", "D": "Có cùng một địa chỉ mạng LAN."}'::jsonb, 'D', 'Đáp án chính xác: D theo bảng chấm điểm chuẩn mã đề 501.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('ltd_p1_c11', 'thpt_le_trung_dinh_0501', '12B', 'Mạng máy tính và Internet', 'single_choice', 'hieu', 'ALL', 'Thẻ HTML nào sau đây được sử dụng để nhúng một tệp âm thanh vào trang web?', '{"A": "<audio>", "B": "<media>", "C": "<sound>", "D": "<music>"}'::jsonb, 'A', 'Đáp án chính xác: A theo bảng chấm điểm chuẩn mã đề 501.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('ltd_p1_c12', 'thpt_le_trung_dinh_0501', '12B', 'Mạng máy tính và Internet', 'single_choice', 'hieu', 'ALL', 'Phương án nào sau đây không là ưu điểm khi mua hàng trên các sàn thương mại điện tử?', '{"A": "Mở rộng khả năng tương tác, tạo cơ hội cho nhiều người dùng chia sẻ quan điểm, sở thích.", "B": "Cải thiện kĩ năng giao tiếp, tạo cơ hội giao tiếp cho nhiều người ở các quốc gia khác nhau.", "C": "Thời gian giao hàng tương đối nhanh chóng, do sự phát triển của các dịch vụ vận chuyển.", "D": "Mọi mặt hàng đều có thể được mua hoặc bán mà không cần quan tâm đến chất lượng."}'::jsonb, 'D', 'Đáp án chính xác: D theo bảng chấm điểm chuẩn mã đề 501.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('ltd_p1_c13', 'thpt_le_trung_dinh_0501', '12B', 'Mạng máy tính và Internet', 'single_choice', 'hieu', 'ALL', 'Trong các khai báo tạo siêu liên kết dưới đây, khai báo nào là đúng?', '{"A": "<a href=  “tranggioithieu.html”> Giới thiệu </a>", "B": "<a href=  “tranggioithieu”> Giới thiệu </a>", "C": "<a href=  “tranggioithieu.html”> Giới thiệu <a>", "D": "<a link=  “tranggioithieu.html”> Giới thiệu <a>"}'::jsonb, 'A', 'Đáp án chính xác: A theo bảng chấm điểm chuẩn mã đề 501.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('ltd_p1_c14', 'thpt_le_trung_dinh_0501', '12B', 'Mạng máy tính và Internet', 'single_choice', 'hieu', 'ALL', 'Chọn một trong hai ngôn ngữ Python hoặc C++ để tìm hiểu chương trình sau:', '{"A": "10", "B": "9", "C": "45", "D": "11"}'::jsonb, 'C', 'Đáp án chính xác: C theo bảng chấm điểm chuẩn mã đề 501.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('ltd_p1_c15', 'thpt_le_trung_dinh_0501', '12B', 'Mạng máy tính và Internet', 'single_choice', 'hieu', 'ALL', 'Ứng dụng công nghệ thông tin trong các ngành kinh tế - xã hội cần nhân lực nào sau đây?', '{"A": "Nhà phân tích dữ liệu.", "B": "Kiểm thử viên.", "C": "Nhà thiết kế giao diện người dùng.", "D": "Chuyên viên thiết kế đồ họa."}'::jsonb, 'A', 'Đáp án chính xác: A theo bảng chấm điểm chuẩn mã đề 501.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('ltd_p1_c16', 'thpt_le_trung_dinh_0501', '12B', 'Mạng máy tính và Internet', 'single_choice', 'hieu', 'ALL', 'Thẻ HTML nào dưới đây được sử dụng để định dạng tiêu đề của một trang web?', '{"A": "<header>", "B": "<head>", "C": "<title>", "D": "<h1>"}'::jsonb, 'C', 'Đáp án chính xác: C theo bảng chấm điểm chuẩn mã đề 501.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('ltd_p1_c17', 'thpt_le_trung_dinh_0501', '12B', 'Mạng máy tính và Internet', 'single_choice', 'hieu', 'ALL', 'Hệ thống AI nào sau đây sử dụng nhận dạng tiếng nói để tương tác với người dùng trong các thiết bị điện thoại thông minh?', '{"A": "Trợ lý ảo Siri.", "B": "Hệ thống nhận dạng khuôn mặt.", "C": "Hệ thống chẩn đoán bệnh.", "D": "Xe tự lái của Tesla."}'::jsonb, 'A', 'Đáp án chính xác: A theo bảng chấm điểm chuẩn mã đề 501.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('ltd_p1_c18', 'thpt_le_trung_dinh_0501', '12B', 'Mạng máy tính và Internet', 'single_choice', 'hieu', 'ALL', 'Thẻ HTML nào sau đây được dùng để in nghiêng nội dung văn bản?', '{"A": "<table> HTMT </table>", "B": "<strong> HTML </strong>", "C": "<mark> HTML </mark>", "D": "<em> HTML</em>"}'::jsonb, 'D', 'Đáp án chính xác: D theo bảng chấm điểm chuẩn mã đề 501.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('ltd_p1_c19', 'thpt_le_trung_dinh_0501', '12B', 'Mạng máy tính và Internet', 'single_choice', 'van_dung', 'ALL', 'Khi cần kết nối một mạng LAN với Internet, loại thiết bị nào sau đây thường được sử dụng?', '{"A": "Hub.", "B": "Switch.", "C": "Modem.", "D": "Access Point."}'::jsonb, 'C', 'Đáp án chính xác: C theo bảng chấm điểm chuẩn mã đề 501.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('ltd_p1_c20', 'thpt_le_trung_dinh_0501', '12B', 'Mạng máy tính và Internet', 'single_choice', 'van_dung', 'ALL', 'Một hệ thống AI giúp bác sĩ xác định bệnh qua hình ảnh y tế như X-quang hoặc MRI là một ví dụ của ứng dụng nào dưới đây?', '{"A": "Chẩn đoán bệnh.", "B": "Nhận dạng khuôn mặt.", "C": "Trợ lý ảo.", "D": "Nhận dạng tiếng nói."}'::jsonb, 'A', 'Đáp án chính xác: A theo bảng chấm điểm chuẩn mã đề 501.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('ltd_p1_c21', 'thpt_le_trung_dinh_0501', '12B', 'Mạng máy tính và Internet', 'single_choice', 'van_dung', 'ALL', 'Công việc nào sau đây thuộc công việc của kĩ sư quản trị mạng?', '{"A": "Lê kế hoạch cho việc nâng cấp và bảo trì thiết bị.", "B": "Khắc phục lỗi, sữa chữa máy tính cho khách hàng.", "C": "Khắc phục sự cố mạng.", "D": "Cập nhật và nâng cấp giải pháp an toàn thông tin cho phù hợp thực tế."}'::jsonb, 'C', 'Đáp án chính xác: C theo bảng chấm điểm chuẩn mã đề 501.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('ltd_p1_c22', 'thpt_le_trung_dinh_0501', '12B', 'Mạng máy tính và Internet', 'single_choice', 'van_dung', 'ALL', 'Cảnh báo nào sau đây liên quan đến sự phát triển quá nhanh của AI?', '{"A": "AI có thể giúp nâng cao sự sáng tạo của con người.", "B": "AI có thể phát triển vượt tầm kiểm soát của con người.", "C": "AI có thể làm cho con người trở nên thông minh hơn.", "D": "AI có thể cải thiện cuộc sống con người một cách nhanh chóng."}'::jsonb, 'B', 'Đáp án chính xác: B theo bảng chấm điểm chuẩn mã đề 501.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('ltd_p1_c23', 'thpt_le_trung_dinh_0501', '12B', 'Mạng máy tính và Internet', 'single_choice', 'van_dung', 'ALL', 'Phương án nào sau đây không là lợi ích của mạng xã hội mang lại?', '{"A": "Thông tin nhanh chóng và rõ ràng giúp tiết kiệm thời gian.", "B": "Vì là không gian ảo, nên mọi thông tin cá nhân đều không có thật.", "C": "Nội dung thông tin phong phú, nhiều lĩnh vực.", "D": "Tạo được sự kết nối với nhiều người trên thế giới."}'::jsonb, 'B', 'Đáp án chính xác: B theo bảng chấm điểm chuẩn mã đề 501.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, options, correct_answer, explanation) VALUES ('ltd_p1_c24', 'thpt_le_trung_dinh_0501', '12B', 'Mạng máy tính và Internet', 'single_choice', 'van_dung', 'ALL', 'Trên một trang web có cụm từ “Trường THPT LTĐ”, nếu muốn tạo liên kết để khi nháy chuột vào từ “THPT LTĐ” sẽ chuyển đến trang chủ của website http://letrungdinh.edu.vn thì cần dùng mã HTML nào sau đây?', '{"A": "<a href = “http://letrungdinh.edu.vn”> Trường THPT LTĐ </a>", "B": "<a href = “http://TruongTHPTLTĐ.edu.vn”>  </a>", "C": "<a href = “TruongTHPTLTĐ”>http:// http://letrungdinh.edu.vn </a>", "D": "<a href = “http://letrungdinh.edu.vn”> THPT LTĐ </a>"}'::jsonb, 'D', 'Đáp án chính xác: D theo bảng chấm điểm chuẩn mã đề 501.') ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, options = EXCLUDED.options, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, statements) VALUES ('ltd_p2_c1', 'thpt_le_trung_dinh_0501', '12F', 'Tạo trang web và thiết kế web', 'true_false_group', 'hieu', 'ALL', 'Câu 1. Trong kì thi tốt nghiệp THPT quốc gia, một trường đã thông tin với học sinh những vật dụng cần thiết khi dự thi. Bạn Bình đã soạn nội dung lưu ý này và đăng lên website cá nhân của bạn. Đoạn mã HTML được soạn có nội dung như sau:', '[{"id": "a", "text": "Có thể click chuột vào dòng chữ “tại đây” để chuyển đến trang chủ website http://truongthptnguyenvana.edu.vn.", "isCorrect": true, "explanation": "Ý (a) là Đúng theo đáp án chuẩn mã 501."}, {"id": "b", "text": "Nội dung “Tẩy” được gạch chân khi hiển thị trên trình duyệt we", "isCorrect": false, "explanation": "Ý (b) là Sai theo đáp án chuẩn mã 501."}, {"id": "c", "text": "Ba nội dung “Bút mực”, “Bút chì” và “Tẩy” được hiển thị dưới dạng danh sách có thứ tự.", "isCorrect": false, "explanation": "Ý (c) là Sai theo đáp án chuẩn mã 501."}, {"id": "d", "text": "Nội dung “Bút chì” được in đậm khi hiển thị trên trình duyệt we", "isCorrect": true, "explanation": "Ý (d) là Đúng theo đáp án chuẩn mã 501."}]'::jsonb) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, statements = EXCLUDED.statements;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, statements) VALUES ('ltd_p2_c2', 'thpt_le_trung_dinh_0501', '12F', 'Tạo trang web và thiết kế web', 'true_false_group', 'hieu', 'ALL', 'Câu 2. Địa chỉ IP là một địa chỉ số được gán cho mỗi thiết bị khi kết nối vào mạng máy tính. Hiện nay, địa chỉ IP có hai phiên bản chính là IPv4 và IPv6. Cho cấu trúc của một địa chỉ IPv4 192.168.1.12. Một số bạn nhận xét về địa chỉ IPv4 trên như sau:', '[{"id": "a", "text": "Địa chỉ máy(Host ID) trong địa chỉ IPv4 trên là 1.12 .", "isCorrect": false, "explanation": "Ý (a) là Sai theo đáp án chuẩn mã 501."}, {"id": "b", "text": "Địa chỉ IPv4 gồm hai phần là địa chỉ mạng (Netwwork ID) và địa chỉ máy (Host ID).", "isCorrect": true, "explanation": "Ý (b) là Đúng theo đáp án chuẩn mã 501."}, {"id": "c", "text": "Địa chỉ IPv4 bao gồm 48 bit.", "isCorrect": false, "explanation": "Ý (c) là Sai theo đáp án chuẩn mã 501."}, {"id": "d", "text": "Khi cài đặt các máy tính trong cùng một mạng LAN sẽ có cùng một địa chỉ mạng.", "isCorrect": true, "explanation": "Ý (d) là Đúng theo đáp án chuẩn mã 501."}]'::jsonb) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, statements = EXCLUDED.statements;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, statements) VALUES ('ltd_p2_c3', 'thpt_le_trung_dinh_0501', '12F', 'Tạo trang web và thiết kế web', 'true_false_group', 'hieu', 'CS', 'Câu 3. Để biết học sinh có hiểu rõ về thuật toán hay không, giáo viên đưa ra dãy số A = [-13, 2, 3, 6, 9, 11, 25, 38, 50, 65], biết chỉ số đầu của A là 0.', '[{"id": "a", "text": "Không áp dụng thuật toán tìm kiếm nhị phân được, vì dãy A có số âm.", "isCorrect": false, "explanation": "Ý (a) là Sai theo đáp án chuẩn mã 501."}, {"id": "b", "text": "Tìm được số 11 ở vị trí 5 và số lần lặp là 3.", "isCorrect": true, "explanation": "Ý (b) là Đúng theo đáp án chuẩn mã 501."}, {"id": "c", "text": "Lần lặp đầu tiên chỉ số đầu bên trái là 0, chỉ số cuối bên phải là 9, chỉ số giữa là 7.", "isCorrect": false, "explanation": "Ý (c) là Sai theo đáp án chuẩn mã 501."}, {"id": "d", "text": "Tìm kiếm nhị phân sẽ có số lần lặp ít hơn tìm kiếm tuần tự.", "isCorrect": true, "explanation": "Ý (d) là Đúng theo đáp án chuẩn mã 501."}]'::jsonb) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, statements = EXCLUDED.statements;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, statements) VALUES ('ltd_p2_c4', 'thpt_le_trung_dinh_0501', '12F', 'Tạo trang web và thiết kế web', 'true_false_group', 'hieu', 'CS', 'Câu 4. Một nhóm bác sĩ đang nghiên cứu sự tác động của các phương pháp điều trị ung thư trên mô phỏng cơ thể người trước khi thực hiện thử nghiệm lâm sàng.', '[{"id": "a", "text": "Mô phỏng giúp đánh giá các phương pháp điều trị để xác định phương pháp an toàn và hiệu quả trước khi thực hiện thử nghiệm trên người.", "isCorrect": true, "explanation": "Ý (a) là Đúng theo đáp án chuẩn mã 501."}, {"id": "b", "text": "Phần mềm mô phỏng có thể thay thế hoàn toàn việc thử nghiệm trên người trong các nghiên cứu y tế.", "isCorrect": false, "explanation": "Ý (b) là Sai theo đáp án chuẩn mã 501."}, {"id": "c", "text": "Mô phỏng trong y tế chỉ có thể mô phỏng các bệnh đơn giản và không thể áp dụng cho các bệnh phức tạp như ung thư.", "isCorrect": false, "explanation": "Ý (c) là Sai theo đáp án chuẩn mã 501."}, {"id": "d", "text": "Mô phỏng trong y tế có thể giúp mô phỏng các phản ứng của cơ thể người đối với thuốc mà không cần thực hiện thử nghiệm trên người.", "isCorrect": true, "explanation": "Ý (d) là Đúng theo đáp án chuẩn mã 501."}]'::jsonb) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, statements = EXCLUDED.statements;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, statements) VALUES ('ltd_p2_c5', 'thpt_le_trung_dinh_0501', '12F', 'Tạo trang web và thiết kế web', 'true_false_group', 'hieu', 'ICT', 'Câu 5. Nhóm học sinh chủ nhiệm Câu lạc bộ (CLB) Tin học cần thiết kế website giới thiệu về CLB gồm ba trang: Giới thiệu, Hoạt động nổi bật, Thông báo sự kiện. Trong lúc thảo luận, các học sinh đưa ra một số nhận định sau:', '[{"id": "a", "text": "Để thu thập thông tin đăng ký tham gia sự kiện của các bạn học sinh trong trường, chỉ có thể sử dụng biểu mẫu (Forms) trên trang Thông báo sự kiện.", "isCorrect": false, "explanation": "Ý (a) là Sai theo đáp án chuẩn mã 501."}, {"id": "b", "text": "Có thể tạo ba trang này từ các mẫu (theme) có sẵn của phần mềm tạo trang we", "isCorrect": true, "explanation": "Ý (b) là Đúng theo đáp án chuẩn mã 501."}, {"id": "c", "text": "Trang Thông báo sự kiện chỉ hiển thị văn bản, không thể chèn hình ảnh hoặc video.", "isCorrect": false, "explanation": "Ý (c) là Sai theo đáp án chuẩn mã 501."}, {"id": "d", "text": "Trang Hoạt động nổi bật có thể hiển thị ảnh theo dạng trình chiếu (Slideshow) để người xem dễ theo dõi.", "isCorrect": true, "explanation": "Ý (d) là Đúng theo đáp án chuẩn mã 501."}]'::jsonb) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, statements = EXCLUDED.statements;
INSERT INTO public.questions (id, exam_id, topic_id, topic_name, type, level, track_requirement, content, statements) VALUES ('ltd_p2_c6', 'thpt_le_trung_dinh_0501', '12F', 'Tạo trang web và thiết kế web', 'true_false_group', 'hieu', 'ICT', 'Câu 6. Một nhóm học sinh đang tiến hành xây dựng và khai thác một cơ sở dữ liệu có tên là QUANLI_HS. Cơ sở dữ liệu này bao gồm các thông tin bên dưới:', '[{"id": "a", "text": "Câu lệnh SQL: SELECT tenHS, bangdiem_th.tb_HK1, bangdiem_th.tb_HK2, (bangdiem_th.tb_HK1+ bangdiem_th.tb_HK2*2)/3 AS “TBCN” FROM tt_hs INNER JOIN bangdiem_th WHERE id_Monhoc = “1”; dùng để liệt kê thông tin của những học sinh có id_monhoc bằng “1”.", "isCorrect": false, "explanation": "Ý (a) là Sai theo đáp án chuẩn mã 501."}, {"id": "b", "text": "Để biết được tên giáo viên chủ nhiệm của một học sinh thì cần phải biết được tên của học sinh đó.", "isCorrect": false, "explanation": "Ý (b) là Sai theo đáp án chuẩn mã 501."}, {"id": "c", "text": "Một số học sinh đưa ra các ý kiến sau:", "isCorrect": true, "explanation": "Ý (c) là Đúng theo đáp án chuẩn mã 501."}, {"id": "d", "text": "Câu lệnh SQL: SELECT id_Monhoc, tb_HK1, tb_HK2 FROM bangdiem_th WHERE id_HS= “1234”; dùng để liệt kê cột tb_HK1 và cột tb_HK2 của tất cả các môn học của học sinh có mã id_HS là “1234”.", "isCorrect": true, "explanation": "Ý (d) là Đúng theo đáp án chuẩn mã 501."}]'::jsonb) ON CONFLICT (id) DO UPDATE SET content = EXCLUDED.content, statements = EXCLUDED.statements;
